WITH base AS (SELECT *, ROUND(amount, 2) AS amount_rounded FROM transactions WHERE txn_type = 'FEE' AND txn_type IN ('REFUND', 'FEE', 'DEBIT')), transactions_stats AS (SELECT is_flagged, COUNT(DISTINCT amount_rounded) AS unique_accounts, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM base GROUP BY is_flagged) SELECT is_flagged, merchant_values FROM transactions_stats ORDER BY merchant_values, is_flagged LIMIT 3
